// Financing uses the same company and ownership record as other services.
(()=>{
const q=s=>document.querySelector(s);
q('#account-type').append(new Option('Financing','financing'));
q('#account-type option[value="both"]').textContent='Both bank and merchant accounts';
const input=(id,title,type='text',required=false)=>`<label class="field"><span>${title}${required?'':' <small>(optional)</small>'}</span><input id="${id}" type="${type}" ${required?'required':''} ${type==='number'?'min="0" step="0.01"':''}></label>`;
const select=(id,title,options,required=true)=>`<label class="field"><span>${title}${required?'':' <small>(optional)</small>'}</span><select id="${id}" ${required?'required':''}><option value="">Select…</option>${options.map(x=>`<option>${x}</option>`).join('')}</select></label>`;
const area=(id,title,required=true)=>`<label class="field"><span>${title}${required?'':' <small>(optional)</small>'}</span><textarea id="${id}" ${required?'required':''}></textarea></label>`;
function page(n,title,lead,body){const s=document.createElement('div');s.className='screen';s.dataset.screen=n;s.hidden=true;s.innerHTML=`<div class="account-section">FINANCING</div><h1>${title}</h1><p class="lead">${lead}</p>${body}`;q('main').append(s);}
page(12,'Your financing request','Tell us what you need to finance.',`<section class="panel">${select('finance-purpose','What is the purpose of the financing?',['Working capital','Business expansion','Equipment or asset purchase','Property acquisition or development','Project finance','Trade or inventory finance','Refinancing existing borrowing','Business acquisition','Other'])}<div id="finance-other" hidden>${input('finance-other-text','Please specify the purpose','text',true)}</div><div class="grid">${input('finance-amount','Amount sought','number',true)}${select('finance-currency','Financing currency',['EUR','GBP','USD','Other'])}</div><div id="finance-currency-other" hidden>${input('finance-currency-code','Other currency code','text',true)}</div>${area('finance-use','How will the funds be used?')}${select('finance-timeline','When do you need the financing?',['Within 1 month','Within 1–3 months','Within 3–6 months','More than 6 months','Flexible / exploring options'])}${input('finance-date','Specific deadline, if any','date')}${input('finance-term','Preferred repayment period, if known')}</section>`);
page(13,'Project & financial information','Share the latest information available.',`<section class="panel">${select('finance-stage','Project or business stage',['Planning / feasibility','Development / pre-launch','Under construction / implementation','Operating / generating revenue','Expansion of an existing business','No separate project — general business financing'])}${area('finance-project','Brief project or business update',false)}</section><section class="panel"><h2>Latest financial information</h2><div class="grid">${select('finance-revenue-status','Revenue status',['Generating revenue','Pre-revenue / no revenue yet','Information not yet available'])}${select('finance-report-currency','Financial reporting currency',['EUR','GBP','USD','Other'])}</div><div id="finance-report-other" hidden>${input('finance-report-code','Other reporting currency','text',true)}</div><div id="finance-revenue-fields" hidden>${input('finance-revenue','Latest annual revenue','number',true)}<div class="grid">${input('finance-period-start','Period start','date',true)}${input('finance-period-end','Period end','date',true)}</div>${area('finance-results','Financial results, where relevant — e.g. profit or loss',false)}</div>${select('finance-audited','Can you share audited financial statements?',['Yes','Available, but sharing needs approval','No audited statements available'])}<div id="finance-audit-fields" hidden><p class="hint">Identify your latest available audited statements.</p><div class="grid">${input('finance-audit-start','Period start','date',true)}${input('finance-audit-end','Period end','date',true)}</div>${select('finance-audit-latest','Are these the latest available audited statements?',['Yes','No — more recent statements are available'])}<div id="finance-audit-newer" hidden>${input('finance-audit-newer-period','Latest available period','text',true)}</div></div><p class="hint">No document upload is required for this initial assessment.</p></section>`);
page(14,'Existing financing & security','Tell us about current borrowing and any available support.',`<section class="panel">${select('finance-existing','Does the company have existing financing?',['Yes','No'])}<div id="finance-existing-fields" hidden>${area('finance-borrowing','List the lenders, financing types, outstanding amounts, currencies and maturity dates')}${area('finance-refinance','Which facilities would be refinanced, if any?',false)}</div></section><section class="panel">${select('finance-security','Are guarantees or assets available to support the financing?',['Yes','No','Not yet determined'])}<div id="finance-security-fields" hidden>${area('finance-security-details','Describe the assets or guarantees and who owns or provides them')}${input('finance-security-value','Estimated value and currency, if known')}${select('finance-pledged','Are these assets already pledged?',['Yes','No','Partly','Not sure'])}</div><p class="hint">Availability does not imply a lender will accept the security.</p></section><p class="hint">Existing bank relationships are collected once in Contact & review.</p>`);
q('#finance-amount').min='0.01';
const conditions=[['finance-purpose','finance-other',v=>v==='Other'],['finance-currency','finance-currency-other',v=>v==='Other'],['finance-report-currency','finance-report-other',v=>v==='Other'],['finance-revenue-status','finance-revenue-fields',v=>v==='Generating revenue'],['finance-audited','finance-audit-fields',v=>v==='Yes'||v==='Available, but sharing needs approval'],['finance-audit-latest','finance-audit-newer',v=>v.startsWith('No')],['finance-existing','finance-existing-fields',v=>v==='Yes'],['finance-security','finance-security-fields',v=>v==='Yes']];
conditions.forEach(([id,target,test])=>q('#'+id).addEventListener('change',()=>q('#'+target).hidden=!test(q('#'+id).value)));
const previousFlow=activeFlow;activeFlow=function(){return q('#account-type').value==='financing'?[0,1,2,12,13,14,4,5]:previousFlow();};
Object.assign(labels,{12:'Financing · Request',13:'Financing · Project & financials',14:'Financing · Borrowing & security'});
const previousSync=syncService;syncService=function(){previousSync();if(q('#account-type').value==='financing'){q('#agent-section').hidden=true;q('#bank-no').hidden=true;q('#combined').hidden=true;}};
q('#account-type').onchange=()=>syncService();
const prevShow=showPage;showPage=function(n){if(q('#account-type').value==='financing'&&activeFlow().indexOf(n)>activeFlow().indexOf(currentPage)){
 const s=q('[data-screen="'+currentPage+'"]');let missing=null;
 if(currentPage===1)missing=['company-name','incorporation','registration'].map(id=>q('#'+id)).find(e=>!e.value.trim());
 if(currentPage===2&&!q('#activity').value.trim())missing=q('#activity');
 if(missing){note('Please complete '+(missing.closest('label')?.querySelector('span')?.textContent||'the required field')+'.');missing.focus();return;}
 for(const pair of [['finance-period-start','finance-period-end'],['finance-audit-start','finance-audit-end']]){const a=q('#'+pair[0]),b=q('#'+pair[1]);if(s.contains(a)&&a.offsetParent!==null&&a.value&&b.value&&a.value>b.value){note('The financial period end must be on or after its start.');b.focus();return;}}
 }prevShow(n);};
const previousReview=review;review=function(){previousReview();if(q('#account-type').value!=='financing')return;const target=q('#review-summary');[...target.querySelectorAll('dt')].filter(t=>t.textContent==='Account currencies').forEach(t=>{t.nextElementSibling.remove();t.remove();});for(const [title,value] of [['Financing purpose',q('#finance-purpose').value],['Amount sought',q('#finance-amount').value+' '+(q('#finance-currency').value==='Other'?q('#finance-currency-code').value:q('#finance-currency').value)],['Use of funds',q('#finance-use').value],['Timeline',q('#finance-timeline').value],['Audited statements',q('#finance-audited').value]]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=title;dd.textContent=value||'Not yet provided';target.append(dt,dd);}};
refreshFlow();
})();
